// Simplified client-side orchestration loop
async function runChain(userGoal, tools) {
  let messages = [{ role: "user", content: userGoal }];

  while (true) {
    const response = await llm.chat({ messages, tools });
    if (response.toolCall) {
      const result = await callTool(response.toolCall.name, response.toolCall.args);
      messages.push({ role: "assistant", content: null, toolCall: response.toolCall });
      messages.push({ role: "tool", content: result });
      continue;
    }
    return response.content;
  }
}

async function researchAndNotify(args) {
  const { query, recipient } = args;

  const rawResults = await searchTool.call({ query });
  const summary = await summarizeTool.call({ text: rawResults.text });
  const sendResult = await sendTool.call({ recipient, message: summary.text });

  return {
    status: "sent",
    summary: summary.text,
    deliveredTo: recipient,
    messageId: sendResult.id
  };
}

async function researchAndNotify(args) {
  const { query, recipient } = args;
  let rawResults, summary;

  try {
    rawResults = await searchTool.call({ query });
  } catch (err) {
    return { status: "failed", step: "search", error: err.message };
  }

  try {
    summary = await summarizeTool.call({ text: rawResults.text });
  } catch (err) {
    return { status: "partial", step: "summarize", error: err.message, rawResults: rawResults.text };
  }

  try {
    const sendResult = await sendTool.call({ recipient, message: summary.text });
    return { status: "sent", summary: summary.text, messageId: sendResult.id };
  } catch (err) {
    return { status: "partial", step: "send", error: err.message, summary: summary.text };
  }
}

async function withRetry(fn, attempts = 2) {
  let lastErr;
  for (let i = 0; i < attempts; i++) {
    try {
      return await fn();
    } catch (err) {
      lastErr = err;
    }
  }
  throw lastErr;
}

