async function dailyDigest(args) {
  const { topic, recipient } = args;

  let rawResults;
  try {
    rawResults = await withRetry(() => searchTool.call({ query: topic }));
  } catch (err) {
    return { status: "failed", step: "search", error: err.message };
  }

  let summary;
  try {
    summary = await summarizeTool.call({ text: rawResults.text, maxWords: 150 });
  } catch (err) {
    return { status: "partial", step: "summarize", error: err.message, rawResults: rawResults.text };
  }

  try {
    const sendResult = await sendTool.call({ recipient, subject: "Daily Digest: " + topic, message: summary.text });
    logger.info("step=digest status=ok recipient=" + recipient);
    return { status: "sent", summary: summary.text, messageId: sendResult.id };
  } catch (err) {
    return { status: "partial", step: "send", error: err.message, summary: summary.text };
  }
}
